    return (
      <>
        {shouldMount ? (renderMethod === 'portal' 
          ? createPortal(dialog(dialogProps), document.body) 
          : dialog(dialogProps)) : null
        }
        {typeof children === 'function' ? children(modalRef) : children}
      </>
    );
  },
  {
    useRef,
  },
);

